import React, { useEffect, useState } from "react";
import { Table, Modal, Button, Form } from "react-bootstrap";
import "../../css/IncomingModule.css";
import * as XLSX from "xlsx";
import {
    getIncomingData,
    allSupplierName,
    saveQaAction,
    getHistoryLogs
} from "../../api/qualityApi";
import { useNavigate } from "react-router-dom";

const IncomingModule = () => {
    const [data, setData] = useState([]);
    const [selectedRow, setSelectedRow] = useState(null);
    const [showModal, setShowModal] = useState(false);
    const [suppliers, setSuppliers] = useState([]);
    const [supplierName, setSupplierName] = useState("");
    const [partType, setPartType] = useState("");

    const [page, setPage] = useState(0);
    const [totalRows, setTotalRows] = useState(0);

    const [passType, setPassType] = useState("BATCH");
    const [docFile, setDocFile] = useState(null);
    const [showDocModal, setShowDocModal] = useState(false);
    const [docUrl, setDocUrl] = useState("");
    const [docType, setDocType] = useState("");
    const [showHistoryModal, setShowHistoryModal] = useState(false);
    const [historyData, setHistoryData] = useState([]);
    const [excelHtml, setExcelHtml] = useState("");
    const [remark, setRemark] = useState("");

    const [filters, setFilters] = useState({
        partName: "",
        supplierName: "",
        partType: "",
        lotNumber: ""
    });

    const navigate = useNavigate();

    // 🔹 Fetch Incoming Data
    const fetchIncoming = async () => {
        try {
            const res = await getIncomingData(page, 10, filters);

            setData(res.data?.data || []);
            setTotalRows(res.data?.total || 0);
        } catch (err) {
            console.error(err);
            setData([]);
        }
    };



    const [excelData, setExcelData] = useState([]);
    const [excelHeaders, setExcelHeaders] = useState([]);

    const loadExcelPreview = async (url) => {
        try {
            const res = await fetch(url);
            const blob = await res.blob();
            const data = await blob.arrayBuffer();

            const workbook = XLSX.read(data, { type: "array" });
            const sheetName = workbook.SheetNames[0];
            const worksheet = workbook.Sheets[sheetName];

            // ✅ Convert to JSON
            const jsonData = XLSX.utils.sheet_to_json(worksheet, { defval: "" });

            // ✅ Extract headers
            const headers = jsonData.length > 0 ? Object.keys(jsonData[0]) : [];

            setExcelHeaders(headers);
            setExcelData(jsonData);

        } catch (err) {
            console.error("Excel preview error:", err);
        }
    };

    // 🔹 Fetch Suppliers
    const fetchSuppliers = async () => {
        try {
            const res = await allSupplierName();
            setSuppliers(res.data || []);
        } catch (err) {
            console.error(err);
        }
    };

    useEffect(() => {
        fetchIncoming();
        fetchSuppliers();

        const interval = setInterval(() => {
            fetchIncoming();
        }, 5000);

        return () => clearInterval(interval);

    }, [page, filters]);



    const handleRowDoubleClick = (row) => {
        const qa = row.qa ? row.qa.trim().toUpperCase() : "";

        if (qa === "EXPIRED") return;

            if (qa === "RERELEASED" || qa === "SCRAPPED" || qa === "SENT BACK") {
        return; 
    }

        if (row.status === "1") return;
        if (row.status === "2") return;
         resetForm();

        setSelectedRow(row);
        setSupplierName(row.supplierName || "");
        setShowModal(true);
    };


    const handleAction = async (type) => {
        try {
            const formData = new FormData();
            formData.append("incomingId", selectedRow.incomingMaterialId);
            formData.append("qaStatus", type);
            formData.append("partType", partType);
            formData.append("passType", passType);
            formData.append("remark", remark);
            formData.append("moduleType", "INCOMING");

            if (docFile) {
                formData.append("document", docFile);
            }

            await saveQaAction(formData);

            setShowModal(false);
            setDocFile(null);
            resetForm();
            fetchIncoming();
        } catch (err) {
            alert("Error saving data");
        }
    };

    const openHistory = async (row) => {
        try {
            const res = await getHistoryLogs(row.incomingMaterialId);
            setHistoryData(res.data || []);
            setShowHistoryModal(true);
        } catch (err) {
            console.log(err);
            alert("Failed to fetch history");
        }
    };

    const resetForm = () => {
        setPartType("");
        setPassType("BATCH");
        setDocFile(null);
        setRemark("");        // ✅ important (your new field)
    };

    return (
        <div className="main-container">


            <div className="incoming-header d-flex justify-content-between align-items-center">

                <h4 className="mb-0">Quality Window</h4>

                <div className="header-pagination d-flex align-items-center gap-2">



                    <Button
                        size="sm"
                        disabled={page === 0}
                        onClick={() => setPage(page - 1)}
                    >
                        ←
                    </Button>

                    <span className="mx-2">Page {page + 1}</span>

                    <Button
                        size="sm"
                        disabled={(page + 1) * 10 >= totalRows}
                        onClick={() => setPage(page + 1)}
                    >
                        →
                    </Button>

                    <Button
                        size="sm"
                        variant="light"
                          onClick={() => window.location.href = "/WebApplication/quality"}
                    >
                        Home
                    </Button>

                </div>

            </div>

            {/* TABLE CARD */}
            <div className="table-wrapper mt-3">
                <div className="table-card">

                    {/* 🔍 FILTER BAR */}
                    <div className="filter-bar">
                        <input
                            placeholder="Part Name"
                            onChange={(e) => {
                                setPage(0);
                                setFilters({ ...filters, partName: e.target.value });
                            }}
                        />

                        <input
                            placeholder="Category"
                            onChange={(e) => {
                                setPage(0);
                                setFilters({ ...filters, category: e.target.value });
                            }}
                        />

                        <input
                            placeholder="Supplier"
                            onChange={(e) => {
                                setPage(0);
                                setFilters({ ...filters, supplierName: e.target.value });
                            }}
                        />

                        <input
                            placeholder="Part Type"
                            onChange={(e) => {
                                setPage(0);
                                setFilters({ ...filters, partType: e.target.value });
                            }}
                        />

                        <input
                            placeholder="Lot No"
                            onChange={(e) => {
                                setPage(0);
                                setFilters({ ...filters, lotNumber: e.target.value });
                            }}
                        />
                    </div>

                    {/* TABLE */}
                    <div className="table-responsive">
                        <Table className="custom-table">
                            <thead className="table-head">
                                <tr>
                                    <th>S.no</th>
                                    <th>Part Name</th>
                                    <th>Category</th>
                                    <th>Supplier</th>
                                    <th>Part Type</th>
                                    <th>Lot No</th>
                                    <th>Qty</th>
                                    <th>MFG Date</th>
                                    <th>Expire Date</th>
                                    <th>Status</th>
                                    <th>Remark</th>
                                    <th>Document</th>
                                    <th>History</th>
                                </tr>
                            </thead>

                            <tbody>
                                {Array.isArray(data) && data.map((row, index) => (


                                    <tr
                                        key={row.incomingMaterialId}
                                        onDoubleClick={() => handleRowDoubleClick(row)}
                                        className={(row.qa || "").trim().toUpperCase() === "EXPIRED" ? "expired-row" : ""}
                                    >
                                        <td>{index + 1 + page * 10}</td>

                                        <td className="fw-semibold">{row.partName}</td>
                                        <td>{row.category || "-"}</td>
                                        <td>{row.supplierName || "-"}</td>
                                        <td>{row.partType || "-"}</td>

                                        <td>{row.lotNumber}</td>
                                        <td>{row.quantity}</td>
                                        <td>{row.mfgDate}</td>
                                        <td>{row.expireDate}</td>
                                        



                                        <td>
                                            {(() => {
                                                const qa = row.qa ? row.qa.trim().toUpperCase() : "";

                                                return (
                                                    <span
                                                        className={
                                                            qa === ""
                                                                ? "status-badge pending"
                                                                : qa === "REJECTED"
                                                                    ? "status-badge rejected"
                                                                    : qa === "RELEASED"
                                                                        ? "status-badge released"
                                                                        : qa === "EXPIRED"
                                                                            ? "status-badge rejected"
                                                                            : "status-badge pending"
                                                        }
                                                    >
                                                        {qa === "" ? "PENDING" : qa}
                                                    </span>
                                                );
                                            })()}
                                        </td>
                                        <td>{row.remark || "-"}</td>
                                        <td>
                                            {row.qaDocPath ? (
                                                <Button
                                                    size="sm"
                                                    variant="info"
                                                    onClick={() => {
                                                        // const url = `/WebApplication/Controllers/viewDoc?path=${row.qaDocPath}`;
                                                        const url = `${window.location.origin}/WebApplication/Controllers/viewDoc?path=${row.qaDocPath}`;
                                                        setDocUrl(url);

                                                        const ext = row.qaDocPath.split(".").pop().toLowerCase();
                                                        setDocType(ext);

                                                        if (ext === "xls" || ext === "xlsx") {
                                                            loadExcelPreview(url);
                                                        }

                                                        setShowDocModal(true);
                                                    }}
                                                >
                                                    View
                                                </Button>
                                            ) : (
                                                "-"
                                            )}
                                        </td>

                                        <td>
                                            <Button
                                                size="sm"
                                                variant="secondary"
                                                onClick={() => openHistory(row)}
                                            >
                                                History
                                            </Button>
                                        </td>

                                    </tr>
                                ))}
                            </tbody>
                        </Table>
                    </div>

                </div>
            </div>

            {/* MODAL */}
            <Modal show={showModal} onHide={() => setShowModal(false)}>
                <Modal.Header closeButton>
                    <Modal.Title>QA Action</Modal.Title>
                </Modal.Header>

                <Modal.Body>
                    <Form>
                        <Form.Group className="mt-2">
                            <Form.Label>Pass Type</Form.Label>
                            <Form.Select value={passType} onChange={(e) => setPassType(e.target.value)}>
                                <option value="BATCH">Batch Pass</option>
                                <option value="LOT">Lot Pass</option>
                            </Form.Select>
                        </Form.Group>

                        <Form.Group className="mt-2">
                            <Form.Label>Remark</Form.Label>
                            <Form.Control
                                as="textarea"
                                rows={2}
                                value={remark}
                                onChange={(e) => setRemark(e.target.value)}
                                placeholder="Enter remark..."
                            />
                        </Form.Group>

                        <Form.Group className="mt-2">
                            <Form.Label>Upload Document</Form.Label>
                            <Form.Control
                                type="file"
                                onChange={(e) => setDocFile(e.target.files[0])}
                            />
                        </Form.Group>

                        <Form.Group className="mt-2">
                            <Form.Label>Part Type</Form.Label>
                            <Form.Control
                                type="text"
                                value={partType}
                                onChange={(e) => setPartType(e.target.value)}
                            />
                        </Form.Group>

                        <Form.Group className="mb-2">
                            <Form.Label>MFG Date</Form.Label>
                            <Form.Control value={selectedRow?.mfgDate || ""} readOnly />
                        </Form.Group>

                        <Form.Group className="mb-2">
                            <Form.Label>Expire Date</Form.Label>
                            <Form.Control value={selectedRow?.expireDate || ""} readOnly />
                        </Form.Group>
                    </Form>
                </Modal.Body>

                <Modal.Footer>
                    <Button variant="success" onClick={() => handleAction("RELEASED")}>
                        Release
                    </Button>
                    <Button variant="danger" onClick={() => handleAction("REJECTED")}>
                        Reject
                    </Button>
                </Modal.Footer>
            </Modal>




            <Modal
                show={showDocModal}
                onHide={() => setShowDocModal(false)}
                size="lg"
            >
                <Modal.Header closeButton>
                    <Modal.Title>View Document</Modal.Title>
                </Modal.Header>

                <Modal.Body style={{ height: "500px" }}>

                    {/* PDF VIEW */}
                    {docType === "pdf" && (
                        <iframe
                            src={docUrl}
                            width="100%"
                            height="100%"
                            style={{ border: "none" }}
                            title="PDF Viewer"
                        />
                    )}

                    {/* IMAGE VIEW */}
                    {(docType === "jpg" || docType === "jpeg" || docType === "png") && (
                        <img
                            src={docUrl}
                            alt="Document"
                            style={{ width: "100%", height: "100%", objectFit: "contain" }}
                        />
                    )}



                    {(docType === "xls" || docType === "xlsx") && (
                        <div className="excel-preview" style={{ overflow: "auto", height: "100%" }}>
                            <table style={{ width: "100%", borderCollapse: "collapse" }}>
                                <thead>
                                    <tr>
                                        {excelHeaders.map((h, i) => (
                                            <th
                                                key={i}
                                                style={{
                                                    backgroundColor: "#198754",
                                                    color: "#fff",
                                                    padding: "8px",
                                                    border: "1px solid #ddd",
                                                    fontWeight: "600"
                                                }}
                                            >
                                                {h}
                                            </th>
                                        ))}
                                    </tr>
                                </thead>

                                <tbody>
                                    {excelData.map((row, i) => (
                                        <tr
                                            key={i}
                                            style={{
                                                backgroundColor: i % 2 === 0 ? "#ffffff" : "#fafafa"
                                            }}
                                        >
                                            {excelHeaders.map((h, j) => (
                                                <td
                                                    key={j}
                                                    style={{
                                                        padding: "6px 10px",
                                                        border: "1px solid #ddd",
                                                        fontSize: "13px"
                                                    }}
                                                >
                                                    {row[h]}
                                                </td>
                                            ))}
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}

                    {/* DEFAULT */}
                    {!(docType === "pdf" ||
                        docType === "jpg" ||
                        docType === "jpeg" ||
                        docType === "png" ||
                        docType === "xls" ||
                        docType === "xlsx") && (
                            <div>
                                <p>Preview not supported.</p>
                                <a href={docUrl} target="_blank" rel="noreferrer">
                                    Download File
                                </a>
                            </div>
                        )}
                </Modal.Body>

                <Modal.Footer>
                    <Button variant="secondary" onClick={() => setShowDocModal(false)}>
                        Close
                    </Button>
                </Modal.Footer>
            </Modal>



            <Modal
                show={showHistoryModal}
                onHide={() => setShowHistoryModal(false)}
                size="lg"
                centered
            >
                <Modal.Header
                    closeButton
                    style={{
                        background: "linear-gradient(135deg, #0f5132, #198754)",
                        color: "white",
                    }}
                >
                    <Modal.Title className="fw-bold">QA History Logs</Modal.Title>
                </Modal.Header>

                <Modal.Body style={{ background: "#f8f9fa" }}>
                    <div
                        style={{
                            background: "white",
                            borderRadius: "12px",
                            padding: "15px",
                            boxShadow: "0 6px 15px rgba(0,0,0,0.08)",
                            maxHeight: "400px",
                            overflowY: "auto",
                        }}
                    >
                        <Table bordered hover responsive className="align-middle mb-0">
                            <thead style={{ background: "#198754", color: "white" }}>
                                <tr>
                                    <th style={{ width: "70px" }}>S.No</th>
                                    <th>QA Status</th>
                                    <th>Created By</th>
                                    <th>Remark</th>
                                    <th>Status</th>

                                    <th>Date Time</th>
                                </tr>
                            </thead>

                            <tbody>
                                {historyData.length > 0 ? (
                                    historyData.map((log, index) => (
                                        <tr key={log.qualityIncomingId}>
                                            <td className="fw-semibold text-center">{index + 1}</td>

                                            <td className="fw-semibold">
                                                <span
                                                    style={{
                                                        padding: "6px 12px",
                                                        borderRadius: "20px",
                                                        fontSize: "12px",
                                                        fontWeight: "600",
                                                        background:
                                                            log.qaStatus?.toUpperCase() === "RELEASED"
                                                                ? "#d1e7dd"
                                                                : log.qaStatus?.toUpperCase() === "REJECTED"
                                                                    ? "#f8d7da"
                                                                    : "#fff3cd",
                                                        color:
                                                            log.qaStatus?.toUpperCase() === "RELEASED"
                                                                ? "#0f5132"
                                                                : log.qaStatus?.toUpperCase() === "REJECTED"
                                                                    ? "#842029"
                                                                    : "#664d03",
                                                    }}
                                                >
                                                    {log.qaStatus || "PENDING"}
                                                </span>
                                            </td>

                                            <td>{log.createdBy || "-"}</td>
                                            <td>{log.remark || "-"}</td>

                                            <td>
                                                <span
                                                    style={{
                                                        padding: "6px 12px",
                                                        borderRadius: "10px",
                                                        fontSize: "12px",
                                                        fontWeight: "600",
                                                        background: "#e9ecef",
                                                        color: "#212529",
                                                    }}
                                                >
                                                    {log.status || "-"}
                                                </span>
                                            </td>

                                            <td style={{ fontSize: "13px", color: "#555" }}>
                                                {log.dateTimeCreation || "-"}
                                            </td>
                                        </tr>
                                    ))
                                ) : (
                                    <tr>
                                        <td colSpan="5" className="text-center text-muted fw-semibold py-3">
                                            No History Found
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </Table>
                    </div>
                </Modal.Body>

                <Modal.Footer style={{ background: "#f8f9fa" }}>
                    <Button variant="secondary" onClick={() => setShowHistoryModal(false)}>
                        Close
                    </Button>
                </Modal.Footer>
            </Modal>
        </div>
    );
};

export default IncomingModule;



