import React, { useState } from "react";
import "../../css/QualityDashboard.css";
import { useNavigate } from "react-router-dom";



const QualityDashboard = () => {

    const [selected, setSelected] = useState("");
    const navigate = useNavigate();

  const handleClick = (type) => {
    setSelected(type);

    if (type === "incoming") {
        navigate("/WebApplication/qualityIncoming");
    } else if (type === "quarantine") {
        navigate("/WebApplication/quarantineWindow");
    }
};

    const goHome = () => {
        window.location.href = "/WebApplication/moduleDashboard";
    };

    return (
        <div className="quality-dashboard">

            {/* HEADER */}
<div className="quality-header">
    <div className="header-left">
        <h2>Quality Modules</h2>
    </div>

    <div className="header-right">

        <button className="qd-home-btn" onClick={goHome}>
            Home
        </button>
    </div>
</div>

            {/* CONTENT */}
            <div className="quality-content">

                <p className="subtitle">Choose a module to continue</p>

                <div className="card-grid">

                    <div
                        className={`q-card ${selected === "incoming" ? "active" : ""}`}
                        onClick={() => handleClick("incoming")}
                    >
                        <div className="icon green">
                            <i className="bi bi-check-circle-fill"></i>
                        </div>
                        <h5>Incoming Quality</h5>
                        <p>Manage incoming inspection and approval process</p>
                    </div>

                    <div
                        className={`q-card ${selected === "quarantine" ? "active" : ""}`}
                        onClick={() => handleClick("quarantine")}
                    >
                        <div className="icon orange">
                            <i className="bi bi-exclamation-triangle-fill"></i>
                        </div>
                        <h5>Quarantine</h5>
                        <p>Handle rejected, expired and blocked materials</p>
                    </div>

                    <div className="q-card disabled">
                        <div className="icon grey">
                            <i className="bi bi-plus-circle-fill"></i>
                        </div>
                        <h5>More Modules</h5>
                        <p>Coming soon...</p>
                    </div>

                </div>
            </div>
        </div>
    );
};

export default QualityDashboard;